@Override public boolean commit() throws LoginException {
  if (auth == null) {
    return false;
  }
  try {
    this.subject.getPrincipals().add(auth.getPrincipal());
    this.subject.getPrivateCredentials().add(auth.getTokenString());
    if (auth.getRoles() != null) {
      for (String roleName : auth.getRoles()) {
        RolePrincipal rolePrinc = new RolePrincipal(roleName);
        this.subject.getPrincipals().add(rolePrinc);
      }
    }
  } catch (UnsupportedOperationException | IllegalArgumentException | ClassCastException e) {
    // Handle the exception, e.g., log it or take corrective action
    e.printStackTrace();
    return false;
  }
  return true;
}
